import heapq


def merge_k_sorted(lists):
    # one heap entry per list: (its next value, which list, the position of that value);
    # the list index comes before anything else that could not be compared, and breaks ties between equal values
    heap = [(lst[0], i, 0) for i, lst in enumerate(lists) if lst]
    heapq.heapify(heap)
    merged = []
    while heap:
        value, i, position = heapq.heappop(heap)
        merged.append(value)
        if position + 1 < len(lists[i]):
            heapq.heappush(heap, (lists[i][position + 1], i, position + 1))
    return merged
